import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const root = resolve(fileURLToPath(new URL("../..", import.meta.url)));
const read = (path) => readFileSync(resolve(root, path), "utf8");
const readJson = (path) => JSON.parse(read(path));

const authorities = {
  ssot: "docs/north-star/agent-operator-score-ssot-v1.0.md",
  adr: "docs/adr/ADR-0003-runtime-repository-and-distribution.md",
  prd: "docs/prd/PRD-D0-name-migration-and-repository-skeleton.md"
};

const supportedContracts = new Map([
  [">=20 <25", [20, 22, 24]],
  [">=22.18 <25", [22, 24]]
]);

const declaredEngineRange = (label, text) => {
  const ranges = [...text.matchAll(/engines\s+`(>=\d+(?:\.\d+)?\s+<\d+)`/g)]
    .map((match) => match[1]);
  const unique = [...new Set(ranges)];
  assert.equal(unique.length, 1, `${label} must declare one unambiguous engines range`);
  assert.ok(supportedContracts.has(unique[0]), `${label} declares an unsupported runtime contract: ${unique[0]}`);
  return unique[0];
};

const ciNodeLanes = (workflow) => {
  const matrices = [...workflow.matchAll(/^\s*node:\s*\[([^\]]+)\]\s*$/gm)];
  assert.equal(matrices.length, 1, "CI must publish one Node test matrix");
  return matrices[0][1]
    .split(",")
    .map((value) => Number(value.trim()))
    .sort((left, right) => left - right);
};

test("published runtime contract agrees with the governing baseline", () => {
  const authorityRanges = Object.entries(authorities).map(([label, path]) =>
    declaredEngineRange(label, read(path))
  );
  const [acceptedRange] = authorityRanges;
  assert.ok(
    authorityRanges.every((range) => range === acceptedRange),
    `governing authorities disagree about the Node baseline: ${authorityRanges.join(", ")}`
  );

  const manifest = readJson("package.json");
  const lock = readJson("package-lock.json");
  assert.equal(
    manifest.engines?.node,
    acceptedRange,
    "the package manager's published Node requirement must match the governing baseline"
  );
  assert.equal(
    lock.packages?.[""]?.engines?.node,
    acceptedRange,
    "the committed install contract must match the published Node requirement"
  );

  assert.deepEqual(
    ciNodeLanes(read(".github/workflows/ci.yml")),
    supportedContracts.get(acceptedRange),
    "CI must test exactly the Node versions promised by the published runtime contract"
  );
});
